// TestStreamRenderGolden 对拍：迁移前后渲染必须逐字节一致（ANSI 剥离后）。
// 等价迁移的证据门——收编 layout.Compute 时本测试零修改零 diff。
func TestStreamRenderGolden(t *testing.T) {
	for name, tc := range goldenStreamRender {
		st := state.NewViewState()
		st.Layout.Width = tc.width
		st.Layout.Height = tc.height
		st.Gateway.Connected = true
		st.Stream = []state.StreamEntry{
			{ID: "u1", Type: "message", Content: "hello stream", Metadata: map[string]any{"role": "user"}},
			{ID: "t1", Type: "tool_start", Content: "", Metadata: map[string]any{"tool": "bash", "input": "ls -la"}},
			{ID: "t2", Type: "tool_end", Content: "total 0", Metadata: map[string]any{"tool": "bash", "status": "ok"}},
			{ID: "a1", Type: "message", Content: "hi there, this is a fairly long assistant line to exercise wrapping behaviour in narrow terminals", Metadata: map[string]any{"role": "assistant"}},
		}
		c := NewAgentStream(st)
		got := stripANSIForGolden(c.View())
		if got != tc.want {
			t.Fatalf("%s: render diff (等价迁移破坏)\n--- got ---\n%q\n--- want ---\n%q", name, got, tc.want)
		}
	}
}

// stripANSIForGolden 剥离 ANSI 转义序列（CSI：ESC [ ... 终止字节）。
func stripANSIForGolden(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] == 0x1b {
			if i+1 < len(s) && s[i+1] == '[' {
				i += 2
				for i < len(s) && !(s[i] >= '@' && s[i] <= '~') {
					i++
				}
				continue
			}
			continue
		}
		b.WriteByte(s[i])
	}
	return b.String()
}
